"""Per-key token bucket replayed over a timeline of events. See task.md."""

from __future__ import annotations

from fractions import Fraction
from math import ceil, floor
from typing import NamedTuple


class ConfigError(ValueError):
    """Raised for an unusable config and for an unusable event stream."""


class Event(NamedTuple):
    timestamp_ms: int
    key: str
    cost: int


class Decision(NamedTuple):
    allowed: bool
    remaining: int
    retry_after_ms: int


def decide(config: dict, events: list[Event]) -> list[Decision]:
    """Replay `events` through a per-key token bucket, one Decision each."""
    for name in ("capacity", "refill_tokens", "refill_interval_ms"):
        if name not in config:
            raise ConfigError(f"missing config key: {name}")
    capacity = config["capacity"]
    refill_tokens = config["refill_tokens"]
    interval = config["refill_interval_ms"]
    if capacity < 1 or refill_tokens < 1 or interval < 1:
        raise ConfigError("capacity, refill_tokens and refill_interval_ms must be >= 1")
    initial = config.get("initial_tokens", capacity)
    if initial < 0 or initial > capacity:
        raise ConfigError("initial_tokens must be within [0, capacity]")

    prev_t = None
    for ev in events:
        if ev.cost < 0:
            raise ConfigError("negative cost")
        if prev_t is not None and ev.timestamp_ms < prev_t:
            raise ConfigError("events are not sorted by timestamp")
        prev_t = ev.timestamp_ms

    rate = Fraction(refill_tokens, interval)
    buckets: dict[str, tuple[int, Fraction]] = {}
    out: list[Decision] = []
    for t, key, cost in events:
        if key in buckets:
            last_t, tokens = buckets[key]
            tokens = min(Fraction(capacity), tokens + (t - last_t) * rate)
        else:
            tokens = Fraction(initial)

        if cost > capacity:
            decision = Decision(False, floor(tokens), -1)
        elif tokens >= cost:
            tokens -= cost
            decision = Decision(True, floor(tokens), 0)
        else:
            wait = ceil((cost - tokens) / rate)
            decision = Decision(False, floor(tokens), wait)
        buckets[key] = (t, tokens)
        out.append(decision)
    return out
